// Przyjmowanie danych ze strony hotelu (np. Pensjonat Syriusz)
const payload = items[0].json.body || items[0].json;

const roomPrices = {
  dwuosobowy: 180,
  trzyosobowy: 250,
  studio: 340
};

const roomType = payload.roomType || 'dwuosobowy';
const pricePerNight = roomPrices[roomType] || 180;

// Kalkulacja szacunkowej ceny
const estimatedTotal = pricePerNight * 2; // Domyślnie 2 doby

return [
  {
    json: {
      status: "success",
      hotel: "Pensjonat Syriusz",
      guestName: payload.name || "Gość",
      email: payload.email || "",
      phone: payload.phone || "",
      roomType: roomType,
      pricePerNight: pricePerNight,
      estimatedTotal: estimatedTotal,
      petsPolicy: "0 zł dopłaty (Gratis)",
      message: `Wstępna rezerwacja zarejestrowana. Szacowany koszt: ${estimatedTotal} zł.`
    }
  }
];
